//! Atomic request admission built on the existing Uh Tom Mick bitpack implementation.
//! This is process-local synchronization, not inter-process shared memory and not IAM.
//! All words are generated by `big_bad_bool::bitpack`; no hand-maintained masks.
use big_bad_bool::bitpack;
// Loom compiles the EXACT SAME admission algorithm against instrumented atomics.
// Only the atomic implementation is selected by this feature; there is no
// test-only copy of the state machine.
#[cfg(feature = "loom")]
use loom::sync::atomic::{AtomicU64, Ordering};
#[cfg(not(feature = "loom"))]
use std::sync::atomic::{AtomicU64, Ordering};

#[bitpack(storage = u64, version = 1)]
pub struct AdmissionWord {
    #[bits(32)]
    active: u32,
    #[bits(1)]
    stopping: u8,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AdmissionError {
    ZeroCapacity,
    AtCapacity { active: u32, limit: u32 },
    Stopping { active: u32 },
}
impl std::fmt::Display for AdmissionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ZeroCapacity => write!(f, "admission capacity must be nonzero"),
            Self::AtCapacity { active, limit } => write!(f, "at capacity ({active}/{limit})"),
            Self::Stopping { active } => {
                write!(f, "daemon stopping with {active} active operations")
            }
        }
    }
}
impl std::error::Error for AdmissionError {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AdmissionSnapshot {
    pub active: u32,
    pub stopping: bool,
}

/// A process-local admission gate. `active` and `stopping` live in one AtomicU64.
/// The successful CAS is the linearization point for admission or shutdown.
#[derive(Debug)]
pub struct AtomicAdmission {
    raw: AtomicU64,
    max_active: u32,
}
impl AtomicAdmission {
    pub fn new(max_active: u32) -> Result<Self, AdmissionError> {
        if max_active == 0 {
            return Err(AdmissionError::ZeroCapacity);
        }
        Ok(Self {
            raw: AtomicU64::new(AdmissionWord::ZERO.raw()),
            max_active,
        })
    }
    pub fn limit(&self) -> u32 {
        self.max_active
    }
    pub fn snapshot(&self) -> AdmissionSnapshot {
        let word = AdmissionWord::try_from_raw_checked(self.raw.load(Ordering::Acquire))
            .expect("only internally validated admission words are published");
        AdmissionSnapshot {
            active: word.active(),
            stopping: word.stopping() != 0,
        }
    }
    pub fn active(&self) -> u32 {
        self.snapshot().active
    }
    pub fn is_stopping(&self) -> bool {
        self.snapshot().stopping
    }
    pub fn is_drained(&self) -> bool {
        let s = self.snapshot();
        s.stopping && s.active == 0
    }
    /// Atomically checks stop/capacity and reserves one active slot.
    /// The returned guard must span the whole async operation (including awaits).
    #[must_use = "dropping the guard immediately releases admission"]
    pub fn try_enter(&self) -> Result<AdmissionGuard<'_>, AdmissionError> {
        match self
            .raw
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |old| {
                let w = AdmissionWord::try_from_raw_checked(old)
                    .expect("only internally validated admission words are published");
                if w.stopping() != 0 || w.active() >= self.max_active {
                    return None;
                }
                Some(w.with_active(w.active() + 1).raw())
            }) {
            Ok(_) => Ok(AdmissionGuard { admission: self }),
            Err(old) => {
                let w = AdmissionWord::try_from_raw_checked(old)
                    .expect("only internally validated admission words are published");
                if w.stopping() != 0 {
                    Err(AdmissionError::Stopping { active: w.active() })
                } else {
                    Err(AdmissionError::AtCapacity {
                        active: w.active(),
                        limit: self.max_active,
                    })
                }
            }
        }
    }
    /// Idempotent. Returns an active count observed at the successful stop CAS,
    /// not a promise that the count remains unchanged after this call.
    pub fn begin_shutdown(&self) -> u32 {
        let old = self
            .raw
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |old| {
                let w = AdmissionWord::try_from_raw_checked(old)
                    .expect("only internally validated admission words are published");
                Some(w.with_stopping(1).raw())
            })
            .expect("shutdown transform always proposes a value");
        AdmissionWord::from_raw(old).active()
    }
    fn leave(&self) {
        // active occupies bits 0..32. A guard exists only after a successful
        // increment, so decrement cannot borrow from the stopping bit.
        let previous = self.raw.fetch_sub(1, Ordering::AcqRel);
        debug_assert!(
            AdmissionWord::from_raw(previous).active() > 0,
            "unbalanced admission guard"
        );
    }
}
/// Intentionally neither Clone nor Copy. A dropped future drops its held guard.
#[derive(Debug)]
#[must_use = "retain until the admitted operation completes"]
pub struct AdmissionGuard<'a> {
    admission: &'a AtomicAdmission,
}
impl Drop for AdmissionGuard<'_> {
    fn drop(&mut self) {
        self.admission.leave();
    }
}

// State capabilities are independent of the admission gate and do not transform
// arbitrary Mutex / Arc / user-authored atomic fields.
pub mod state;
pub use state::{AtomicCounter, AtomicFlagSet, CounterError, FlagSetError};

/// A single coherent observation of the admission/shutdown lifecycle.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DrainStatus {
    Open { active: u32 },
    Stopping { active: u32 },
    Drained,
}
impl AtomicAdmission {
    /// Observational: neither awaits nor automatically closes admission.
    /// After Drained, the count cannot increase because admission is closed.
    pub fn drain_status(&self) -> DrainStatus {
        match self.snapshot() {
            AdmissionSnapshot {
                active,
                stopping: false,
            } => DrainStatus::Open { active },
            AdmissionSnapshot {
                active: 0,
                stopping: true,
            } => DrainStatus::Drained,
            AdmissionSnapshot {
                active,
                stopping: true,
            } => DrainStatus::Stopping { active },
        }
    }
}
